CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS bureaus(id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','officer','viewer')), bureau TEXT REFERENCES bureaus(id));
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS institutions(id TEXT PRIMARY KEY, permanent_id TEXT NOT NULL UNIQUE, name TEXT NOT NULL, region TEXT NOT NULL, address TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS aliases(name TEXT PRIMARY KEY, institution_id TEXT NOT NULL REFERENCES institutions(id));
CREATE TABLE IF NOT EXISTS sla_policies(category TEXT PRIMARY KEY, days INTEGER NOT NULL CHECK(days BETWEEN 1 AND 365), rule TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cases(id TEXT PRIMARY KEY, institution_id TEXT REFERENCES institutions(id), institution_input TEXT NOT NULL, permanent_input TEXT NOT NULL DEFAULT '', region_input TEXT NOT NULL, identity_state TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, category TEXT NOT NULL REFERENCES sla_policies(category), period TEXT NOT NULL, evidence_ref TEXT NOT NULL DEFAULT '', bureau TEXT NOT NULL REFERENCES bureaus(id), officer_id TEXT REFERENCES users(id), status TEXT NOT NULL CHECK(status IN ('Pending','Under Process','Disposed','Transferred','Escalated')), received_at TEXT NOT NULL, due_at TEXT NOT NULL, updated_at TEXT NOT NULL, next_action TEXT NOT NULL DEFAULT '', source TEXT NOT NULL, source_id TEXT NOT NULL, synced_at TEXT NOT NULL, restricted INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1, UNIQUE(source,source_id));
CREATE INDEX IF NOT EXISTS cases_institution_idx ON cases(institution_id);
CREATE INDEX IF NOT EXISTS cases_status_bureau_idx ON cases(status,bureau);
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES cases(id), actor_id TEXT NOT NULL REFERENCES users(id), bureau TEXT REFERENCES bureaus(id), action TEXT NOT NULL, remarks TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS events_no_update BEFORE UPDATE ON events BEGIN SELECT RAISE(ABORT,'Audit events are append-only'); END;
CREATE TRIGGER IF NOT EXISTS events_no_delete BEFORE DELETE ON events BEGIN SELECT RAISE(ABORT,'Audit events are append-only'); END;
CREATE TABLE IF NOT EXISTS relationships(id TEXT PRIMARY KEY, case_a TEXT NOT NULL REFERENCES cases(id), case_b TEXT NOT NULL REFERENCES cases(id), kind TEXT NOT NULL, score REAL NOT NULL, reasons TEXT NOT NULL, decision TEXT, justification TEXT, reviewer_id TEXT REFERENCES users(id), reviewed_at TEXT, version INTEGER NOT NULL DEFAULT 1, UNIQUE(case_a,case_b));
CREATE TABLE IF NOT EXISTS coordination_tasks(id TEXT PRIMARY KEY, relationship_id TEXT NOT NULL REFERENCES relationships(id), officer_id TEXT NOT NULL REFERENCES users(id), due_at TEXT NOT NULL, next_action TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'Open', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), case_id TEXT REFERENCES cases(id), message TEXT NOT NULL, kind TEXT NOT NULL, read_at TEXT, created_at TEXT NOT NULL, dedup_key TEXT NOT NULL, UNIQUE(user_id,dedup_key));
CREATE TABLE IF NOT EXISTS documents(id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES cases(id), uploader_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL, mime TEXT NOT NULL, content BLOB NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS import_runs(id TEXT PRIMARY KEY, source TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES users(id), count INTEGER NOT NULL, skipped INTEGER NOT NULL, created_at TEXT NOT NULL);
